CREATE COLUMN TABLE "TEST_AP"."OSCD" ("AbsEntry" INTEGER CS_INT NOT NULL , "County" INTEGER CS_INT NOT NULL , "ServiceCD" NVARCHAR(15) NOT NULL , "Descrip" NVARCHAR(70), "Incomimg" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSCD_CODE" ON "TEST_AP"."OSCD" ( "County" ASC, "ServiceCD" ASC )